// Writes src/environments/environment.generated.ts from .env (or .env.example when .env is missing,
// as in CI). Runs before start, build and test; the generated file is not committed.
import { existsSync, mkdirSync, writeFileSync } from 'node:fs';

const source = existsSync('.env') ? '.env' : '.env.example';
process.loadEnvFile(source);

const keys = ['API_BASE_URL', 'API_AUTH_SIGN_IN_PATH', 'API_AUTH_ACTIVATION_PATH', 'API_AUTH_ACTIVATE_PATH', 'API_EMPLOYEES_PATH', 'API_CONTRACTS_PATH', 'API_WORK_SCHEDULES_PATH'];
const missing = keys.filter(key => !process.env[key]);
if (missing.length) throw new Error(`Missing in ${source}: ${missing.join(', ')}`);

const environment = Object.fromEntries(keys.map(key => [key, process.env[key]]));
mkdirSync('src/environments', { recursive: true });
writeFileSync('src/environments/environment.generated.ts',
  `// Generated by scripts/generate-env.mjs from ${source}. Do not edit or commit.\nexport const environment = ${JSON.stringify(environment, null, 2)} as const;\n`);
console.log(`Environment generated from ${source}`);
